import {moods,messages,createDeck} from './messages.js';
import {track} from './analytics.js';
export function initExperience({storage,toast,tone,magic,enterWorld,reduced}){
const $=s=>document.querySelector(s),draw=createDeck();let mood='gentle',current=null,rituals=0,folded=false,skyTimer,breathTimer=null,breathStart=0,lastPhase=-1;
const allMessages=new Map(Object.values(messages).flat().map(m=>[m.id,m]));
let ids=storage.get('savedMessages',[]);if(!Array.isArray(ids))ids=[];const saved=new Set(ids.filter(id=>typeof id==='string'&&allMessages.has(id)).slice(0,100));
function updateSaved(){const active=saved.has(current?.id);$('#save-message').textContent=active?'♥ Đã giữ':'♡ Giữ lại';$('#save-message').setAttribute('aria-pressed',String(active));$('#saved-count').textContent=saved.size}
function showNote(group=mood,origin='Một lời nhắn dành cho bạn',animate=true){current=draw(group);$('#companion').hidden=false;folded=false;$('#companion-content').hidden=false;$('#fold-companion').textContent='−';$('#fold-companion').setAttribute('aria-label','Thu gọn lời nhắn');$('#blessing-origin').textContent=origin;$('#blessing-title').textContent=current.title;$('#blessing-text').textContent=current.text;$('#blessing-detail').textContent=group==='gaming'?'Ngoài game, bạn vẫn là bạn.':'Cứ đọc chậm thôi.';$('#blessing').dataset.kind=group;updateSaved();if(animate&&!reduced){$('#blessing').getAnimations().forEach(a=>a.cancel());$('#blessing').animate([{opacity:.1,transform:'translateY(12px)'},{opacity:1,transform:'translateY(0)'}],{duration:600,easing:'cubic-bezier(.16,1,.3,1)'})}}
for(const [id,label,icon] of moods){const b=document.createElement('button');b.type='button';b.dataset.mood=id;b.textContent=icon+' '+label;b.setAttribute('aria-pressed',String(id===mood));b.onclick=()=>{mood=id;$('#moods').querySelectorAll('button').forEach(el=>el.setAttribute('aria-pressed',String(el===b)));showNote(mood,'Dành cho lúc bạn '+label.toLowerCase());magic('mood');tone()};$('#moods').append(b)}
function sky(text){clearTimeout(skyTimer);$('#sky-message p').textContent=text;$('#sky-message').classList.remove('visible');requestAnimationFrame(()=>$('#sky-message').classList.add('visible'));skyTimer=setTimeout(()=>$('#sky-message').classList.remove('visible'),4800)}
function ritual(kind){track('interaction_completed',{activity:kind==='breath'?'breathing':'world'});rituals++;const useMood=mood!=='gentle'&&rituals%2===0;const origin={lamp:'Một ngọn đèn vừa sáng vì bạn',bell:'Sau một tiếng chuông ngân',wish:'Gửi theo chiếc đèn của bạn',breath:'Sau một khoảng nghỉ nhỏ'}[kind];showNote(useMood?mood:kind,origin);magic(kind);sky({lamp:'Mong bạn gặp những điều dịu dàng.',bell:'Buông một điều. Nhẹ một chút.',wish:'Gửi hy vọng vào một khoảng trời.',breath:'Cảm ơn vì đã dành thời gian cho mình.'}[kind]);if(!reduced){$('#ritual-flash').getAnimations().forEach(a=>a.cancel());$('#ritual-flash').animate([{opacity:0},{opacity:.65,offset:.2},{opacity:0}],{duration:1300})}}
$('#another-note').onclick=()=>{showNote(mood);magic('note');tone()};$('#open-companion').onclick=()=>{enterWorld();showNote(mood);track('feature_opened',{feature_name:'notes'})};
$('#fold-companion').onclick=()=>{folded=!folded;$('#companion-content').hidden=folded;$('#fold-companion').textContent=folded?'+':'−';$('#fold-companion').setAttribute('aria-label',folded?'Mở lời nhắn':'Thu gọn lời nhắn')};
$('#save-message').onclick=()=>{if(!current)return;const old=new Set(saved);if(saved.has(current.id))saved.delete(current.id);else saved.add(current.id);if(!storage.set('savedMessages',[...saved])){saved.clear();old.forEach(id=>saved.add(id));toast('Trình duyệt chưa cho lưu. Bạn có thể đọc lời nhắn ở đây.')}else {if(saved.has(current.id))track('interaction_completed',{activity:'saved_note'});toast(saved.has(current.id)?'Đã giữ lời nhắn trong góc riêng của bạn.':'Đã bỏ lời nhắn khỏi mục đã giữ.');}updateSaved()};
function renderJournal(){const root=$('#saved-messages');root.replaceChildren();if(!saved.size){const p=document.createElement('p');p.className='empty-journal';p.textContent='Chưa có lời nhắn nào ở đây. Chọn “♡ Giữ lại” ở câu bạn muốn mang theo.';root.append(p);return}for(const id of [...saved].reverse()){const m=allMessages.get(id),a=document.createElement('article'),h=document.createElement('h3'),p=document.createElement('p'),b=document.createElement('button');a.className='saved-note';h.textContent=m.title;p.textContent=m.text;b.type='button';b.textContent='Đọc trong cảnh';b.onclick=()=>{$('#journal-dialog').close();enterWorld();current=m;$('#companion').hidden=false;$('#companion-content').hidden=false;folded=false;$('#fold-companion').textContent='−';$('#fold-companion').setAttribute('aria-label','Thu gọn lời nhắn');$('#blessing-origin').textContent='Một lời bạn đã giữ';$('#blessing-title').textContent=m.title;$('#blessing-text').textContent=m.text;$('#blessing').dataset.kind=m.group;updateSaved()};a.append(h,p,b);root.append(a)}}
$('#open-journal').onclick=()=>{renderJournal();$('#journal-dialog').showModal()};
function resetBreath(){clearInterval(breathTimer);breathTimer=null;lastPhase=-1;$('#breath-orb').classList.remove('inhale','exhale','running');$('#start-breath').hidden=false;$('#stop-breath').hidden=true;$('#breath-cue').textContent='Sẵn sàng chưa?';$('#breath-time').textContent='Khoảng nghỉ 30 giây';$('#start-breath').textContent='Bắt đầu khoảng nghỉ ◉'}
function tickBreath(){const elapsed=(performance.now()-breathStart)/1000;if(elapsed>=30){resetBreath();$('#breath-dialog').close();ritual('breath');return}const phase=Math.floor(elapsed/5)%2;if(phase!==lastPhase){lastPhase=phase;$('#breath-orb').classList.toggle('inhale',phase===0);$('#breath-orb').classList.toggle('exhale',phase===1);$('#breath-cue').textContent=phase===0?'Hít vào nhẹ nhàng':'Thở ra, thả lỏng';tone(phase===1)}$('#breath-time').textContent=Math.ceil(30-elapsed)+' giây cho bạn'}
$('#open-breath').onclick=()=>{track('feature_opened',{feature_name:'breathing'});resetBreath();$('#breath-dialog').showModal()};$('#start-breath').onclick=()=>{breathStart=performance.now();$('#start-breath').hidden=true;$('#stop-breath').hidden=false;$('#breath-orb').classList.add('running');tickBreath();breathTimer=setInterval(tickBreath,200)};$('#stop-breath').onclick=()=>{resetBreath();$('#breath-dialog').close();showNote('breath','Một khoảng dừng theo nhịp của bạn')};$('#breath-dialog').addEventListener('close',resetBreath);document.addEventListener('visibilitychange',()=>{if(document.hidden&&breathTimer){resetBreath();$('#breath-cue').textContent='Bắt đầu lại khi bạn sẵn sàng'}});
updateSaved();return{enter(){showNote(mood,'Chào bạn. Ở đây không cần gồng.')},ritual};
}
